const DRV='#7A1240',DRVC='#F4DDE6';
const hrow=(icon,c,t,time,sub='',chev=false)=>`<div class="item" style="min-height:60px;align-items:flex-start;padding:14px 14px"><div class="ic" style="background:${c};color:#fff">${ic(icon,19,'#fff')}</div><div class="t" style="font-size:16px;line-height:1.35;padding-top:${sub?0:9}px">${t}${sub}</div><span class="muted" style="font-size:14px;padding-top:${sub?1:10}px;font-variant-numeric:tabular-nums">${time}</span>${chev?`<div style="padding-top:${sub?0:8}px">${ic('chevron-right',20,'var(--onv)')}</div>`:''}</div>`;
const chips=(a)=>`<div style="display:flex;gap:5px;margin-top:8px;flex-wrap:nowrap">${a.map(([i,t])=>`<span style="display:inline-flex;align-items:center;gap:4px;background:${DRVC};color:${DRV};border-radius:8px;padding:4px 7px;white-space:nowrap;font-size:14px;font-weight:500">${ic(i,13,DRV,2.2)}${t}</span>`).join('')}</div>`;
const line=(t)=>`<div style="font-size:14px;color:var(--onv);margin-top:3px;line-height:1.4">${t}</div>`;
const tabs=(on)=>`<div style="padding:4px 16px 10px"><div class="seg">${['Members','Places','History','Settings'].map(t=>`<div class="${t===on?'on':''}">${t}</div>`).join('')}</div></div>`;
const dayH=(t)=>`<div class="day" style="font-size:14px;color:var(--p);letter-spacing:0;font-weight:500">${t}</div>`;
const sw=(on,dis=false)=>`<div style="width:52px;height:32px;border-radius:16px;background:${on?'var(--p)':'var(--sch)'};border:2px solid ${on?'var(--p)':'var(--ol)'};position:relative;flex:none;${dis?'opacity:.38':''}"><div style="position:absolute;top:${on?3:6}px;${on?'right:3px':'left:6px'};width:${on?22:16}px;height:${on?22:16}px;border-radius:11px;background:${on?'#fff':'var(--ol)'}"></div></div>`;
const foot=(t)=>`<div style="font-size:14px;color:var(--onv);margin:10px 26px 0;line-height:1.45">${t}</div>`;
const memberSw=(i,c,name,state,on,dis=false)=>`<div class="row" style="border-top:1px solid var(--sch);padding:12px 0;align-items:center">${av(i,40,c)}<div class="sp" style="font-size:17px">${name}${state?`<div style="font-size:14px;color:var(--onv);line-height:1.35">${state}</div>`:''}</div>${sw(on,dis)}</div>`;
const dIc=(s=20)=>`<div class="ic" style="background:${DRVC};color:${DRV}">${ic('car',s,DRV)}</div>`;
const drow=(t,s,on,chev=false)=>`<div class="item">${dIc()}<div class="t">${t}${s?`<small>${s}</small>`:''}</div>${on==null?'':sw(on)}${chev?ic('chevron-right',20,'var(--onv)'):''}</div>`;
const navrow=(icon,t,s)=>`<div class="item"><div class="ic">${ic(icon,20)}</div><div class="t">${t}<small>${s}</small></div>${ic('chevron-right',20,'var(--onv)')}</div>`;
const gav=(c,name)=>`<div style="width:40px;height:40px;border-radius:20px;background:${c}22;display:flex;align-items:center;justify-content:center;flex:none;color:${c};font-weight:600;font-size:16px">${name[0]}</div>`;
